async (page) => {
  const passed=[]; const check=(ok,name)=>{if(!ok)throw Error(name);passed.push(name)};
  const url='http://127.0.0.1:5189/tests/fixtures/desktop.html?scene=piranha&width=440&canvas=1';
  await page.goto(url);await page.locator('.piranha-character .piranha-sprite[data-ready=true]').waitFor();
  await page.emulateMedia({reducedMotion:'reduce'});
  check(await page.locator('.piranha-motion').evaluate(e=>getComputedStyle(e).animationName==='none'),'system reduced motion respected');
  await page.emulateMedia({reducedMotion:'no-preference'});
  await page.locator('.piranha-widget').hover();
  await page.getByRole('button',{name:'食人花换装',exact:true}).click();await page.getByRole('button',{name:'樱花款',exact:true}).click();await page.keyboard.press('Escape');
  await page.evaluate(async()=>{await window.emUse.settings({scene:'buddy'});await window.emUse.settings({scene:'piranha'});});
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.piranhaSkin)==='sakura','scene switch preserves independent skin');
  await page.locator('.piranha-widget').hover();await page.getByRole('button',{name:'食人花更多玩法',exact:true}).click();
  await page.locator('.piranha-play-grid button').filter({hasText:'合苞小憩'}).click();
  await page.evaluate(()=>window.emUse.settings({scene:'buddy'}));
  await page.locator('.buddy-widget').waitFor();
  await page.evaluate(()=>window.emUse.settings({scene:'piranha'}));
  await page.locator('.piranha-character').waitFor();
  check(await page.locator('.piranha-character').getAttribute('data-action')==='idle','scene unmount clears persistent pose');
  await page.locator('.piranha-widget').hover();
  await page.locator('.piranha-resize.se').focus();await page.keyboard.press('ArrowUp');
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.windowWidth)===450,'keyboard resize delegates to shared settings');
  await page.mouse.move(200,200);await page.keyboard.down('Control');await page.mouse.wheel(0,-40);await page.keyboard.up('Control');
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.windowWidth)>450,'modifier wheel uses shared resize');
  await page.goto(url+'&update=available&platform=macos');
  await page.locator('.piranha-widget').hover();
  await page.getByRole('button',{name:/花种补给袋：新版本/}).click();
  check(await page.getByRole('dialog',{name:'花种补给站 · 版本更新'}).isVisible(),'dedicated update prop opens shared letter');
  check(await page.getByRole('button',{name:'前往下载',exact:true}).isVisible(),'mac update retains manual-download contract');
  await page.getByRole('button',{name:'稍后更新，关闭来信',exact:true}).click();
  await page.route('**/assets/piranha/character-atlas.png',route=>route.abort());
  await page.goto(url+'&quota=none');
  await page.locator('.piranha-character .piranha-asset-error').waitFor();
  check(await page.locator('.piranha-quota').innerText().then(s=>s.includes('—')),'failed art does not invent quota');
  await page.unroute('**/assets/piranha/character-atlas.png');
  await page.locator('.piranha-character').getByRole('button',{name:'重试',exact:true}).click();
  await page.locator('.piranha-character .piranha-sprite[data-ready=true]').waitFor();
  check(await page.locator('.piranha-character .piranha-asset-error').count()===0,'asset retry recovers actual canvas');
  return passed;
}
